export function translateUiText(value, language) {
  if (!value) return value;
  const text = String(value);
  // Russian must also work when a component renders English/German text directly.
  // Build a reverse dictionary from existing translations instead of leaving those strings untranslated.
  let dict;
  if (language === 'ru') {
    dict = {};
    for (const sourceDict of [UI_TRANSLATIONS.en, UI_TRANSLATIONS.de, EXTRA_TRANSLATIONS.en, EXTRA_TRANSLATIONS.de, APP_TEXT_TRANSLATIONS.en, APP_TEXT_TRANSLATIONS.de]) {
      for (const [ru, translated] of Object.entries(sourceDict || {})) {
        if (translated && !Object.prototype.hasOwnProperty.call(dict, translated)) dict[translated] = ru;
      }
    }
  } else {
    dict = { ...(UI_TRANSLATIONS[language] || {}), ...(EXTRA_TRANSLATIONS[language] || {}), ...(APP_TEXT_TRANSLATIONS[language] || {}) };
  }
  const trimmed = text.trim();
  if (Object.prototype.hasOwnProperty.call(dict, trimmed)) return text.replace(trimmed, dict[trimmed]);
  let result = text;
  const entries = Object.entries(dict).filter(([source]) => source && source.length > 1).sort((a,b) => b[0].length-a[0].length);
  for (const [source, target] of entries) {
    let from = 0;
    while (true) {
      const at = result.indexOf(source, from);
      if (at < 0) break;
      const before = at > 0 ? result[at-1] : '';
      const after = at + source.length < result.length ? result[at+source.length] : '';
      const word = ch => !!ch && /[A-Za-zА-Яа-яЁё0-9_]/.test(ch);
      if (!word(before) && !word(after)) {
        result = result.slice(0,at) + target + result.slice(at+source.length);
        from = at + target.length;
      } else from = at + source.length;
    }
  }
  return result;
}


const translatedNodes = new WeakMap();
const translatedAttributes = new WeakMap();
const TRANSLATABLE_ATTRIBUTES = ['placeholder', 'title', 'aria-label', 'alt'];

export function observeUiTranslations(language, root = document.getElementById('root')) {
  if (!root) return () => {};
  let applying = false;
  const translateNode = node => {
    if (node.nodeType === Node.TEXT_NODE) {
      const raw = node.nodeValue || '';
      if (!raw.trim()) return;
      let state = translatedNodes.get(node);
      if (!state) state = { original: raw, translated: null };
      else if (raw !== state.translated) state.original = raw;
      const next = translateUiText(state.original, language);
      state.translated = next;
      translatedNodes.set(node, state);
      if (raw !== next) node.nodeValue = next;
      return;
    }
    if (node.nodeType !== Node.ELEMENT_NODE) return;
    const element = node;
    if (['SCRIPT', 'STYLE', 'NOSCRIPT', 'SVG', 'PATH'].includes(element.tagName)) return;
    for (const attr of TRANSLATABLE_ATTRIBUTES) {
      if (!element.hasAttribute(attr)) continue;
      const raw = element.getAttribute(attr) || '';
      let map = translatedAttributes.get(element);
      if (!map) { map = new Map(); translatedAttributes.set(element, map); }
      let state = map.get(attr);
      if (!state) state = { original: raw, translated: null };
      else if (raw !== state.translated) state.original = raw;
      const next = translateUiText(state.original, language);
      state.translated = next;
      map.set(attr, state);
      if (raw !== next) element.setAttribute(attr, next);
    }
    for (const child of element.childNodes) translateNode(child);
  };
  const run = () => {
    if (applying) return;
    applying = true;
    try { translateNode(root); } finally { applying = false; }
  };
  run();
  const observer = new MutationObserver(records => {
    if (applying) return;
    applying = true;
    try {
      for (const record of records) {
        if (record.type === 'characterData') translateNode(record.target);
        else if (record.type === 'attributes') translateNode(record.target);
        else for (const node of record.addedNodes) translateNode(node);
      }
    } finally { applying = false; }
  });
  observer.observe(root, { childList: true, subtree: true, characterData: true, attributes: true, attributeFilter: TRANSLATABLE_ATTRIBUTES });
  return () => observer.disconnect();
}
